const fs = require('node:fs');
const crypto = require('node:crypto');
const directory = 'products/services/contracts-finder-small-data-job/';
const feedBytes = fs.readFileSync(directory + 'official-feed.json');
const sha256 = crypto.createHash('sha256').update(feedBytes).digest('hex');
const expected = '33d85ed3b5e0b38258cf283e4a3481dec45102ba444b62c0f83230a8b3e5b6e0';
if (sha256 !== expected) throw new Error('Feed bytes differ from the recorded FETCH receipt');
const feed = JSON.parse(feedBytes);
const releases = feed.releases.filter(release => release.tender);
if (releases.length !== 9) throw new Error('Tender count differs from the recorded screen');
const terms = /\b(?:csv|spreadsheet|file conversion|data clean(?:ing|sing)|export validation|data migration|conformance|data quality)\b/i;
const rows = releases.map(release => {
  const tender = release.tender;
  const fields = [{field: 'tender.title', text: tender.title}, {field: 'tender.description', text: tender.description}];
  for (const lot of tender.lots ?? []) {
    fields.push({field: 'lot.title', lot: lot.id, text: lot.title}, {field: 'lot.description', lot: lot.id, text: lot.description});
  }
  const matchedFields = fields.filter(field => typeof field.text === 'string' && terms.test(field.text)).map(({field, lot, text}) => ({field, lot, matchedTerm: text.match(terms)[0]}));
  return {releaseId: release.id, tenderId: tender.id, title: tender.title, status: tender.status ?? null, deadline: tender.tenderPeriod?.endDate ?? null, lots: (tender.lots ?? []).map(lot => ({id: lot.id, title: lot.title ?? null})), matchedFields};
});
const result = {sourceReceipt: 'TASK-179502876101', sourceSha256: sha256, publishedFromUtc: '2026-11-17T00:00:00Z', publishedToUtc: '2026-11-18T00:00:00Z', releaseCount: releases.length, status: 'TRIAGE_ONLY', limitation: 'Keyword matches flag fields for manual review. Absence of a match does not rule out a standalone job. The feed alone does not establish eligibility or a permitted submission route.', rows};
const output = directory + 'source-verified-triage.json';
fs.writeFileSync(output, JSON.stringify(result, null, 2) + '\n');
const readback = JSON.parse(fs.readFileSync(output, 'utf8'));
if (readback.sourceSha256 !== sha256 || readback.rows.length !== releases.length) throw new Error('Readback failed');
console.log(JSON.stringify({output, releaseCount: readback.releaseCount, matchedReleaseCount: readback.rows.filter(row => row.matchedFields.length).length}));
